const $=s=>document.querySelector(s);let state={coins:350,wins:0,name:'Dagg',gender:'Kvinnlig',skin:'#efc6a1',hair:'#784c39',outfit:'#b68bc2',frog:'#88ad55',owned:[],hatched:false,eggClicks:0,hairstyle:'long',pattern:'plain',baseStats:[45,55,40]};try{const s=JSON.parse(localStorage.getItem('grodgaloppen'));if(s&&Number.isFinite(s.coins)&&Array.isArray(s.owned))state={...state,...s}}catch{}let tab='race',chosen=0,running=false;const races=[{name:'Näckrosdammen',icon:'❀',type:'FART',desc:'Hoppa mellan näckrosor i den soliga dammen.',reward:90,stat:0},{name:'Svampskogen',icon:'🍄',type:'HOPP',desc:'Ta stora språng över rötter och svampar.',reward:110,stat:1},{name:'Månskensmyren',icon:'☾',type:'UTHÅLLIGHET',desc:'Håll hela vägen genom den magiska myren.',reward:130,stat:2}];const items=[{id:'goggles',name:'Racingglasögon',icon:'🥽',desc:'Klar sikt, snabba språng.',cost:150,stat:0,bonus:22},{id:'boots',name:'Studsstövlar',icon:'👢',desc:'Lite extra studs över varje rot.',cost:180,stat:1,bonus:25},{id:'charm',name:'Daggamulett',icon:'💎',desc:'Skogens energi, hela vägen i mål.',cost:200,stat:2,bonus:25},{id:'scarf',name:'Vindhalsduk',icon:'🧣',desc:'Fånga vinden på din nästa tävling.',cost:120,stat:0,bonus:13}];function save(){try{localStorage.setItem('grodgaloppen',JSON.stringify(state))}catch{toast('Webbläsaren kunde inte spara framstegen.')}}function stats(){const a=[...state.baseStats];items.forEach(i=>{if(state.owned.includes(i.id))a[i.stat]+=i.bonus});return a}function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),3000)}
function frog(color=state.frog,player=true){return `<svg viewBox="0 0 280 240" xmlns="http://www.w3.org/2000/svg"><ellipse cx="145" cy="216" rx="105" ry="12" fill="#344d3020"/>${player?`<g stroke="#fff6ec" stroke-width="2"><ellipse cx="137" cy="80" rx="19" ry="43" transform="rotate(-40 137 80)" fill="#f5e6fb" opacity=".8"/><ellipse cx="167" cy="78" rx="16" ry="39" transform="rotate(35 167 78)" fill="#e3f0f6" opacity=".8"/></g><path d="M148 112 Q137 130 125 147 L157 153 165 113" fill="${state.outfit}"/><path d="M146 134 L161 154 181 157" fill="none" stroke="${state.skin}" stroke-width="9" stroke-linecap="round"/><path d="M159 112 L178 131 195 129" fill="none" stroke="${state.skin}" stroke-width="7" stroke-linecap="round"/><path d="M133 83 Q130 51 152 53 Q178 54 169 91" fill="${state.hair}"/><ellipse cx="153" cy="80" rx="16" ry="20" fill="${state.skin}"/><path d="M136 74 Q147 78 151 62 Q165 63 170 77 Q172 51 150 54 Q132 55 136 74" fill="${state.hair}"/>${hairShape()}<circle cx="159" cy="80" r="2" fill="#364032"/><path d="M155 91 Q160 94 164 89" stroke="#b17a64" fill="none"/><path d="M140 56 Q148 37 158 55 Q170 44 171 57" fill="#c4d88a"/>`:''}<ellipse cx="135" cy="178" rx="76" ry="36" fill="${color}"/><ellipse cx="84" cy="188" rx="36" ry="25" fill="${color}"/><path d="M68 200 Q47 214 27 207 M86 204 Q74 220 58 213 M163 200 Q181 218 213 208" fill="none" stroke="${color}" stroke-width="13" stroke-linecap="round"/><ellipse cx="194" cy="160" rx="50" ry="34" fill="${color}"/><ellipse cx="190" cy="141" rx="17" ry="23" fill="${color}"/><ellipse cx="222" cy="143" rx="14" ry="20" fill="${color}"/><ellipse cx="194" cy="140" rx="10" ry="14" fill="#f7f1c9"/><ellipse cx="224" cy="141" rx="8" ry="12" fill="#f7f1c9"/><ellipse cx="197" cy="141" rx="4" ry="8" fill="#293f2d"/><ellipse cx="226" cy="142" rx="3" ry="7" fill="#293f2d"/><path d="M181 169 Q208 188 235 165" fill="none" stroke="#46603a" stroke-width="3" stroke-linecap="round"/><ellipse cx="178" cy="165" rx="9" ry="5" fill="#ceac79" opacity=".6"/><ellipse cx="142" cy="190" rx="43" ry="14" fill="#d4df9a" opacity=".55"/>${player?patternShape():''}${player&&state.owned.includes('goggles')?'<g fill="#b6e4eaa0" stroke="#725a39" stroke-width="5"><rect x="180" y="129" width="28" height="25" rx="9"/><rect x="213" y="130" width="25" height="24" rx="8"/><path d="M207 141h6"/></g>':''}${player&&state.owned.includes('scarf')?'<path d="M170 180 Q148 183 130 172 L105 185 141 190 166 189" fill="#d98769"/>':''}</svg>`}
function scene(){return `<svg viewBox="0 0 900 340" preserveAspectRatio="xMidYMid slice"><defs><linearGradient id="bg" x2="0" y2="1"><stop stop-color="#e8edcb"/><stop offset="1" stop-color="#a8c5a0"/></linearGradient></defs><rect width="900" height="340" fill="url(#bg)"/><circle cx="671" cy="77" r="58" fill="#f7efb7" opacity=".7"/><path d="M0 175 Q110 90 220 169 T450 151 T710 130 T950 150V340H0" fill="#b0c293"/><path d="M0 233 Q170 150 320 215 T650 196 T950 206V340H0" fill="#83a97c"/><path d="M0 278 Q260 191 450 245 Q650 287 900 215V340H0" fill="#aacbb4"/><g fill="none" stroke="#e1ecce" opacity=".6"><ellipse cx="560" cy="300" rx="210" ry="16"/><ellipse cx="725" cy="248" rx="87" ry="8"/></g><g fill="#648a58"><path d="M438 293 Q510 257 583 289 Q530 320 438 293L500 289Z"/><path d="M715 300 Q765 270 824 298 Q772 322 715 300L770 297Z"/><path d="M325 260 Q355 242 398 259 Q365 275 325 260Z"/></g><g stroke="#5e8152" stroke-width="5"><path d="M860 340Q835 227 853 160M875 340Q901 230 884 194M32 340Q48 264 23 225"/></g><g fill="#826c43"><rect x="846" y="143" width="13" height="55" rx="6"/><rect x="879" y="179" width="12" height="49" rx="6"/></g><g fill="#f6e9a8"><circle cx="380" cy="111" r="3"/><circle cx="731" cy="160" r="3"/><circle cx="469" cy="73" r="3"/></g><g transform="translate(380 35) scale(1.1)">${frog().replace(/<svg[^>]*>|<\/svg>/g,'')}</g><g fill="#efc8cb"><ellipse cx="752" cy="287" rx="6" ry="16" transform="rotate(-30 752 287)"/><ellipse cx="765" cy="286" rx="6" ry="16" transform="rotate(25 765 286)"/></g></svg>`}
function sidebar(){$('#coins').textContent=state.coins;$('#wins').textContent=state.wins+' segrar';$('#teamName').textContent=state.name+' & Näckros';$('#portrait').innerHTML=frog();$('#stats').innerHTML=stats().map((n,i)=>`<div class="stat"><span>${['Fart','Hopp','Uthållighet'][i]}</span><div class="bar"><i style="width:${n}%"></i></div><span>${n}</span></div>`).join('')}
function render(){if(!state.hatched){renderEgg();return}document.body.classList.remove('hatching');sidebar();document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.tab===tab));const c=$('#content');if(tab==='race'){const r=races[chosen];c.innerHTML=`<div class="sectionHead"><h2>Välj ditt nästa äventyr</h2><span class="pill">3 race att upptäcka</span></div><div class="hero">${scene()}<div class="heroText"><span class="pill">✦ ÄLVSKOGENS FAVORIT</span><h2>Små språng.<br>Stor magi.</h2><p>Sadla din groda. Äventyret börjar vid vattenbrynet.</p></div></div><div class="raceCards">${races.map((x,i)=>`<article class="card ${i===chosen?'selected':''}"><span class="icon">${x.icon}</span><h3>${x.name}</h3><p>${x.desc}</p><div class="meta"><span>✧ ${x.type}</span><span>✦ ${x.reward}</span></div><button aria-label="Välj ${x.name}" data-race="${i}" aria-pressed="${i===chosen}"></button></article>`).join('')}</div><div class="raceBottom"><div style="font-size:12px">${r.name}<small>Gratis att delta · 4 tävlande · cirka 20 sekunder</small></div><button class="primary" id="start">Till startlinjen →</button></div>`;document.querySelectorAll('[data-race]').forEach(b=>b.onclick=()=>{chosen=+b.dataset.race;render()});$('#start').onclick=startRace}else if(tab==='frog'){c.innerHTML=`<div class="sectionHead"><h2>Näckros utrustningsbod</h2><span class="pill">Alla bonusar är aktiva</span></div><div class="shop">${items.map(i=>`<article class="card"><div class="icon">${i.icon}</div><h3>${i.name}</h3><p>${i.desc}<br>+${i.bonus} ${['fart','hopp','uthållighet'][i.stat]}</p><button class="primary" data-buy="${i.id}" ${state.owned.includes(i.id)||state.coins<i.cost?'disabled':''}>${state.owned.includes(i.id)?'✓ Utrustad':'✦ '+i.cost+' · Köp'}</button></article>`).join('')}</div><div class="editor" style="margin-top:18px"><h3>En groda i din färg</h3><div class="options">${['#88ad55','#66aaa0','#c49b57','#9c8db5'].map(v=>`<button aria-label="Grodfärg ${v}" class="swatch ${state.frog===v?'chosen':''}" style="background:${v}" data-frog="${v}"></button>`).join('')}</div></div>`;document.querySelectorAll('[data-buy]').forEach(b=>b.onclick=()=>{const i=items.find(i=>i.id===b.dataset.buy);if(!state.owned.includes(i.id)&&state.coins>=i.cost){state.coins-=i.cost;state.owned.push(i.id);save();render();toast(i.name+' är nu utrustade!')}});document.querySelectorAll('[data-frog]').forEach(b=>b.onclick=()=>{state.frog=b.dataset.frog;save();render()})}else{c.innerHTML=`<div class="sectionHead"><h2>Din älva, din stil</h2><span class="pill">Alla stilar är gratis</span></div><div class="editor"><div style="height:190px;text-align:center">${frog()}</div><label for="name">Älvans namn</label><input type="text" id="name" maxlength="18"><label>Frisyr</label><div class="options hairstyles">${[['short','Kort'],['long','Långt'],['curly','Lockigt'],['braid','Fläta']].map(([v,n])=>`<button data-style="${v}" aria-pressed="${state.hairstyle===v}" class="${state.hairstyle===v?'chosen':''}">${n}</button>`).join('')}</div><label>Älvans utseende</label><div class="options">${['Kvinnlig','Manlig'].map(v=>`<button data-gender="${v}" class="${state.gender===v?'chosen':''}">${v} älva</button>`).join('')}</div>${[['skin','Hudfärg',['#f7dfcc','#efc6a1','#d6a077','#b77b55','#89563d','#57382c']],['hair','Hårfärg',['#784c39','#e5c681','#333638','#ce795e']],['outfit','Klädfärg',['#b68bc2','#79a7c0','#d99783','#789d61']]].map(([key,label,colors])=>`<label>${label}</label><div class="options">${colors.map(v=>`<button aria-label="${label} ${v}" aria-pressed="${state[key]===v}" data-key="${key}" data-color="${v}" class="swatch ${state[key]===v?'chosen':''}" style="background:${v}"></button>`).join('')}</div>`).join('')}<p>✧ Din stil sparas automatiskt och följer med ut på banan.</p></div>`;document.querySelectorAll('[data-style]').forEach(b=>b.onclick=()=>{state.hairstyle=b.dataset.style;save();render()});$('#name').value=state.name;$('#name').oninput=e=>{state.name=e.target.value.trim()||'Dagg';save();sidebar()};document.querySelectorAll('[data-gender]').forEach(b=>b.onclick=()=>{state.gender=b.dataset.gender;save();render()});document.querySelectorAll('[data-color]').forEach(b=>b.onclick=()=>{state[b.dataset.key]=b.dataset.color;save();render()})}}
function startRace(){if(!state.hatched)return;running=true;let progress=[0,0,0,0],finished=[],boosts=3,last=performance.now(),elapsed=0;const r=races[chosen],strength=stats()[r.stat];$('#content').innerHTML=`<div class="sectionHead"><h2>${r.name}</h2><span class="pill">✧ ${r.type} ger fördel</span></div><div class="track">${['Ditt team','Klöver','Mossa','Pärla'].map((n,i)=>`<div style="font-size:11px;margin-top:12px">${n}</div><div class="lane"><div class="racer" id="racer${i}">${frog(i?['','#b3a15e','#71a6a0','#aa89ae'][i]:state.frog,i===0)}</div></div>`).join('')}</div><div class="raceInfo" aria-live="polite"><h2 id="raceTitle">Nu går starten!</h2><p id="raceHelp">Ge Näckros extra fart med tre magiska språng.</p><button id="boost" class="primary">✦ Magiskt språng (3)</button></div>`;$('#boost').onclick=()=>{if(boosts>0&&!finished.includes(0)){boosts--;progress[0]+=4;$('#boost').textContent='✦ Magiskt språng ('+boosts+')';$('#boost').disabled=boosts===0}};const speeds=[3.4+strength*.022,4.7+Math.random()*.7,4.6+Math.random()*.8,4.8+Math.random()*.65];function frame(now){const dt=Math.min((now-last)/1000,.1);last=now;elapsed+=dt;progress=progress.map((p,i)=>Math.min(100,p+dt*speeds[i]*(.88+Math.random()*.24)));progress.forEach((p,i)=>{$('#racer'+i).style.left=`calc(${p*.85}% - ${p*.15}px)`});progress.map((p,i)=>({p,i})).filter(x=>x.p>=100&&!finished.includes(x.i)).sort((a,b)=>b.p-a.p).forEach(x=>finished.push(x.i));if(elapsed>2)$('#raceTitle').textContent=finished.includes(0)?'I mål!':'Heja '+state.name+'!';if(finished.includes(0)){running=false;const rank=finished.indexOf(0)+1,reward=Math.round(r.reward*[1,.65,.4,.25][rank-1]);state.coins+=reward;if(rank===1)state.wins++;save();sidebar();$('.raceInfo').innerHTML=`<h2>${rank===1?'🏆 Seger i dammen!':'Fint sprunget! Plats '+rank+' av 4'}</h2><p>Du vann ${reward} daggdroppar. ${rank===1?'Skogen jublar för ditt team!':'Uppgradera din groda och prova igen.'}</p><button class="primary" id="again">Tillbaka till loppen →</button>`;$('#again').onclick=render;return}requestAnimationFrame(frame)}requestAnimationFrame(frame)}
function hairShape(){const c=state.hair;return ({short:`<path d="M134 68L137 50 148 56 158 49 169 66" fill="${c}"/>`,long:`<path d="M135 68 Q120 92 134 119" stroke="${c}" stroke-width="14" fill="none"/>`,curly:`<g fill="${c}"><circle cx="133" cy="67" r="10"/><circle cx="138" cy="53" r="10"/><circle cx="152" cy="51" r="10"/><circle cx="166" cy="58" r="10"/><circle cx="130" cy="81" r="9"/><circle cx="133" cy="94" r="9"/></g>`,braid:`<g fill="${c}" stroke="#fff2" stroke-width="1"><ellipse cx="133" cy="79" rx="8" ry="12"/><ellipse cx="131" cy="92" rx="7" ry="10"/><ellipse cx="133" cy="104" rx="6" ry="9"/><ellipse cx="131" cy="115" rx="5" ry="8"/></g><path d="M125 119h12" stroke="${state.outfit}" stroke-width="4"/>`})[state.hairstyle]||''}
function patternShape(){if(state.pattern==='spots')return '<g fill="#263c43" opacity=".45"><circle cx="87" cy="175" r="5"/><circle cx="108" cy="163" r="5"/><circle cx="128" cy="174" r="5"/><circle cx="149" cy="159" r="4"/><circle cx="104" cy="190" r="4"/><circle cx="166" cy="171" r="4"/></g>';if(state.pattern==='patches')return '<g fill="#f5e7c2" opacity=".65"><path d="M73 174Q74 157 94 164T108 184Q93 199 80 184Z"/><path d="M120 163Q128 145 146 156T144 177Q125 182 120 163Z"/><path d="M153 180Q161 170 174 183T160 197Z"/></g>';return ''}
function eggArt(){const n=Math.min(4,state.eggClicks);return `<svg viewBox="0 0 320 310" aria-hidden="true"><defs><radialGradient id="jelly"><stop stop-color="#f1fff7" stop-opacity=".25"/><stop offset=".75" stop-color="#c4e7d8" stop-opacity=".45"/><stop offset="1" stop-color="#f4fffa" stop-opacity=".9"/></radialGradient></defs><ellipse cx="160" cy="278" rx="112" ry="17" fill="#6d987c" opacity=".25"/><path d="M47 274Q140 227 275 268Q190 305 47 274L140 271Z" fill="#8aab72"/><ellipse cx="160" cy="156" rx="105" ry="114" fill="url(#jelly)" stroke="#f7fff9" stroke-width="3"/><ellipse cx="162" cy="166" rx="46" ry="52" fill="#364a40"/><ellipse cx="150" cy="149" rx="28" ry="32" fill="#526359"/><path d="M86 132Q89 87 121 75" stroke="white" stroke-width="10" opacity=".65" stroke-linecap="round" fill="none"/><circle cx="234" cy="194" r="9" fill="white" opacity=".4"/><g stroke="#efffe9" stroke-width="3" fill="none" stroke-linejoin="round">${n>0?'<path d="M162 112L150 139 168 151 157 175"/>':''}${n>1?'<path d="M157 175L181 185 167 219"/>':''}${n>2?'<path d="M168 151L192 140 205 157M150 139L127 151 116 143"/>':''}${n>3?'<path d="M157 175L134 188 124 211M181 185L204 199"/>':''}</g><g fill="#fff9cb"><path d="M258 68l3 9 9 3-9 3-3 9-3-9-9-3 9-3Z"/><circle cx="59" cy="205" r="3"/></g></svg>`}
function renderEgg(){document.body.classList.add('hatching');$('#coins').textContent=state.coins;$('#content').innerHTML=`<section class="eggScreen"><div class="eyebrow">DITT ÄVENTYR BÖRJAR HÄR</div><h2>Vem gömmer sig i ägget?</h2><p>Ett litet grodägg i en magisk gelébubbla.<br>Klicka fem gånger och möt din nya vän.</p><button class="eggButton" aria-label="Klicka på det mystiska ägget">${eggArt()}</button><div class="eggProgress" aria-label="${state.eggClicks} av 5 klick">${[0,1,2,3,4].map(i=>`<span class="${i<state.eggClicks?'filled':''}"></span>`).join('')}</div><p role="status">${['Ett försiktigt klick kan väcka någon där inne…','Det rör sig i ägget!','En liten spricka… fortsätt!','Snart får du träffa din groda!','Bara ett klick till!'][state.eggClicks]||''}</p></section>`;$('.eggButton').onclick=()=>{state.eggClicks=Math.min(5,state.eggClicks+1);if(state.eggClicks===5){const pick=a=>a[Math.floor(Math.random()*a.length)];state.frog=pick(['#88ad55','#66aaa0','#c49b57','#9c8db5','#cc8d9c','#82b8cf']);state.pattern=pick(['plain','spots','patches']);state.baseStats=[0,1,2].map(()=>35+Math.floor(Math.random()*26));state.hatched=true;save();showHatched()}else{save();renderEgg()}}}
function showHatched(){$('#content').innerHTML=`<section class="eggScreen reveal"><div class="eyebrow">VÄLKOMMEN TILL VÄRLDEN</div><h2>Du fick Näckros!</h2><div class="newFrog">${frog()}</div><p>${{plain:'En enfärgad',spots:'En prickig',patches:'En fläckig'}[state.pattern]} liten groda, redo för äventyr.</p><div class="hatchStats">${state.baseStats.map((v,i)=>`<div><strong>${v}</strong><span>${['Fart','Hopp','Uthållighet'][i]}</span></div>`).join('')}</div><p>Det här är din grodas grundegenskaper.<br>Utrustning gör den ännu bättre!</p><button class="primary" id="meetFairy">Välj din älvas frisyr →</button></section>`;$('#meetFairy').onclick=()=>{tab='fairy';render()}}
document.querySelectorAll('nav button').forEach(b=>b.onclick=()=>{if(running){toast('Gör klart racet först – heja ditt team!');return}tab=b.dataset.tab;render()});$('#customize').onclick=()=>{if(running)return;tab='fairy';render()};render();
